@app.command()
def run(
    question: str = typer.Option(..., "--question", "-q"),
    max_papers: int = typer.Option(None, "--max-papers"),
    config: str = typer.Option("configs/default.yaml", "--config"),
    fixture: bool = typer.Option(False, "--fixture"),
) -> None:
    run_id = f"{datetime.now(timezone.utc):%Y%m%dT%H%M%SZ}-{uuid.uuid4().hex[:8]}"
    overrides: dict | None = None
    if max_papers is not None:
        overrides = {"review": {"max_papers": max_papers}}
    cfg = load_config(config, overrides=overrides)

    with TraceLogger(run_id, runs_dir=cfg.output.runs_dir) as trace:
        trace.event(
            agent="cli",
            event="run_start",
            payload={
                "question": question,
                "fixture": fixture,
                "config": cfg.model_dump(),
            },
        )
        typer.echo(f"run_id={run_id}")
        typer.echo(f"run_dir={trace.run_dir}")
        trace.event(agent="cli", event="run_end", payload={"ok": True})


if __name__ == "__main__":
    app()
=== run_pipeline signature ===
def run_pipeline(
    research_question: str,
    cfg: Any,
    *,
    run_id: str | None = None,
    max_papers: int | None = None,
    write_artefacts: bool = True,
) -> ReviewState:
    """Run PLANNER -> ... -> WRITER and write the run's artefacts."""
    run_id = run_id or f"run_{uuid.uuid4().hex[:10]}"
    if max_papers is not None:
        cfg = cfg.model_copy(
            update={"review": cfg.review.model_copy(update={"max_papers": max_papers})}
        )

    trace = TraceLogger(run_id=run_id, runs_dir=cfg.output.runs_dir)
    llm = LLMClient(cfg.llm, trace=trace)
    state: dict[str, Any] = {
        "run_id": run_id,
        "research_question": research_question,
        "iteration": 0,
        "constraints": {"year_min": cfg.review.year_min,
                        "max_papers": cfg.review.max_papers},
    }

    trace.event("graph", "run_start", {"research_question": research_question,
                                       "max_papers": cfg.review.max_papers,
                                       "model": cfg.llm.model}, 0)
    try:
        for agent in make_agents(cfg, llm, trace):
            _merge(state, agent(state))

        if write_artefacts:
            state.setdefault("artefacts", {})
            run_dir = pathlib.Path(trace.run_dir)

