// Verify Panel 3's sentence -> claim matching against the REAL fixture.
//
// This is the one genuinely risky piece of the front end: the Verifier strips
// [n] markers when it decomposes, while review.md carries them, so the match is
// by normalised text rather than offset. If normalisation drifts from what
// agents/verifier.py did, the panel silently highlights nothing and the "money
// shot" is an empty page.
import fs from 'node:fs'

const dir = 'outputs/runs/fixture'
const review = fs.readFileSync(`${dir}/review.md`, 'utf8')
const claims = JSON.parse(fs.readFileSync(`${dir}/claims.json`, 'utf8'))

// Identical to PanelEvidence.vue::normalise
const normalise = (s) =>
  (s || '')
    .replace(/\[\d+\]/g, ' ')
    .replace(/[*_`#]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .toLowerCase()

const byText = new Map()
for (const c of claims.verified) {
  const k = normalise(c.text)
  if (k) byText.set(k, c)
}

let sentences = 0
let matched = 0
const misses = []

for (const raw of review.split('\n')) {
  const line = raw.trimEnd()
  if (!line.trim()) continue
  if (/^#{1,6}\s/.test(line) || line.startsWith('|') || line.startsWith('---')) continue
  for (const part of line.split(/(?<=[.!?])\s+(?=[A-Z0-9"'(\[])/)) {
    sentences += 1
    if (byText.get(normalise(part))) matched += 1
  }
}

for (const c of claims.verified) {
  const k = normalise(c.text)
  const found = review.split('\n').some((l) =>
    l.split(/(?<=[.!?])\s+(?=[A-Z0-9"'(\[])/).some((p) => normalise(p) === k))
  if (!found) misses.push(c.claim_id)
}

console.log(`review sentences        : ${sentences}`)
console.log(`verified claims         : ${claims.verified.length}`)
console.log(`sentences highlighted   : ${matched}`)
console.log(`claims NOT located      : ${misses.length} ${misses.slice(0, 5).join(', ')}`)
console.log(`dropped claims (panel 4): ${claims.dropped.length}`)
const withEvidence = claims.verified.filter((c) => c.evidence.length).length
console.log(`claims WITH an evidence span: ${withEvidence}/${claims.verified.length}`)

if (matched === 0) {
  console.error('\nFAIL: nothing would highlight - Panel 3 would render as plain prose.')
  process.exit(1)
}

